#[inline]
fn ge_allow_eq<T: TotalOrd>(l: &T, r: &T, allow_eq: bool) -> bool {
    match l.tot_cmp(r) {
        Ordering::Equal => allow_eq,
        Ordering::Greater => true,
        Ordering::Less => false,
    }
}

#[inline]
fn lt_allow_eq<T: TotalOrd>(l: &T, r: &T, allow_eq: bool) -> bool {
    match l.tot_cmp(r) {
        Ordering::Equal => allow_eq,
        Ordering::Less => true,
        Ordering::Greater => false,
    }
}

