                for sf in stop_and_take_pipe_contents(recv_left.as_mut()).await {
                    left_buffer.push_back(sf.into_df().await);
                }
                return Ok(());
            }
        }

        if params.as_of_options().check_sortedness {
            check_left_continuity(last_non_null_row_left, &left_df, params)?;
        }

        if !params.as_of_options().check_sortedness {

